import{_ as p,a0 as o,w as r,s as d,I as n,x as a,a1 as i,A as t,ao as l}from"./chunks/framework.ePQ6-oQR.js";import"./chunks/theme.D0YJYoYq.js";const C=JSON.parse('{"title":"如何修复使用 Python ORM 工具 SQLAlchemy 时的常见陷阱 | LCTT x X-CMD","titleTemplate":false,"description":"如何修复使用 Python ORM 工具 SQLAlchemy 时的常见陷阱 | LCTT (201911) | X-CMD","frontmatter":{"pageClass":"x-lctt","head":[["meta",{"name":"og:title","content":"如何修复使用 Python ORM 工具 SQLAlchemy 时的常见陷阱 | LCTT x X-CMD"}],["meta",{"name":"og:description","content":"如何修复使用 Python ORM 工具 SQLAlchemy 时的常见陷阱 | LCTT (201911) | X-CMD"}]]},"headers":[],"params":{"isLCTT":true,"post":"201911/20190912 How to fix common pitfalls with the Python ORM tool SQLAlchemy","title":"如何修复使用 Python ORM 工具 SQLAlchemy 时的常见陷阱","tag":"201911","desc":""},"relativePath":"201911/20190912 How to fix common pitfalls with the Python ORM tool SQLAlchemy.md","filePath":"[post].md"}'),h={name:"201911/20190912 How to fix common pitfalls with the Python ORM tool SQLAlchemy.md"};function c(u,s,g,b,k,m){const e=o("Link");return r(),d("div",null,[s[24]||(s[24]=n("h1",{id:"如何修复使用-python-orm-工具-sqlalchemy-时的常见陷阱",tabindex:"-1"},[a("如何修复使用 Python ORM 工具 SQLAlchemy 时的常见陷阱 "),n("a",{class:"header-anchor",href:"#如何修复使用-python-orm-工具-sqlalchemy-时的常见陷阱","aria-label":"Permalink to “如何修复使用 Python ORM 工具 SQLAlchemy 时的常见陷阱”"},"​")],-1)),s[25]||(s[25]=n("blockquote",null,[n("p",null,"在使用 SQLAlchemy 时，那些看似很小的选择可能对这种对象关系映射工具包的性能产生重要影响。")],-1)),s[26]||(s[26]=n("p",null,[n("img",{src:"https://opensource.com/sites/default/files/styles/image-full-size/public/lead-images/python_snake_file_box.jpg?itok=UuDVFLX-",alt:"A python with a package.",title:"A python with a package."})],-1)),n("p",null,[s[2]||(s[2]=n("ruby",null,[a("对象关系映射"),n("rt",null,"Object-relational mapping")],-1)),s[3]||(s[3]=a("（",-1)),i(e,{href:"https://en.wikipedia.org/wiki/Object-relational_mapping"},{default:t(()=>[...s[0]||(s[0]=[a("ORM",-1)])]),_:1}),s[4]||(s[4]=a("）使应用程序开发人员的工作更轻松，在很大程度是因为它允许你使用你可能知道的语言（例如 Python）与数据库交互，而不是使用原始 SQL 语句查询。",-1)),i(e,{href:"https://www.sqlalchemy.org/"},{default:t(()=>[...s[1]||(s[1]=[a("SQLAlchemy",-1)])]),_:1}),s[5]||(s[5]=a(" 是一个 Python ORM 工具包，它提供使用 Python 访问 SQL 数据库的功能。它是一个成熟的 ORM 工具，增加了模型关系、强大的查询构造范式、简单的序列化等优点。然而，它的易用性使得人们很容易忘记其背后发生了什么。使用 SQLAlchemy 时做出的看似很小的选择可能产生非常大的性能影响。",-1))]),s[27]||(s[27]=l(`<p>本文解释了开发人员在使用 SQLAlchemy 时遇到的一些最重要的性能问题，以及如何解决这些问题。</p><h3 id="只需要计数但检索整个结果集" tabindex="-1">只需要计数但检索整个结果集 <a class="header-anchor" href="#只需要计数但检索整个结果集" aria-label="Permalink to “只需要计数但检索整个结果集”">​</a></h3><p>有时开发人员只需要一个结果计数，但是没有使用数据库计数功能，而是获取了所有结果，然后使用 Python 中的 <code>len</code> 完成计数。</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>count = len(User.query.filter_by(acct_active=True).all())</span></span></code></pre></div><p>相反，使用 SQLAlchemy 的 <code>count</code> 方法将在服务器端执行计数，从而减少发送到客户端的数据。在前面的例子中调用 <code>all()</code> 也会导致模型对象的实例化，如果有很多数据，那么时间代价可能会非常昂贵。</p><p>除非还需要做其他的事情，否则只需使用 <code>count</code> 方法：</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>count = User.query.filter_by(acct_active=True).count()</span></span></code></pre></div><h3 id="只需要几列时检索整个模型" tabindex="-1">只需要几列时检索整个模型 <a class="header-anchor" href="#只需要几列时检索整个模型" aria-label="Permalink to “只需要几列时检索整个模型”">​</a></h3><p>在许多情况下，发出查询时只需要几列数据。SQLAlchemy 可以只获取你想要的列，而不是返回整个模型实例。这不仅减少了发送的数据量，还避免了实例化整个对象。使用列数据的元组而不是模型可以快得多。</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>result = User.query.all()</span></span>
<span class="line"><span>for user in result:</span></span>
<span class="line"><span>    print(user.name, user.email)</span></span></code></pre></div><p>反之，使用 <code>with_entities</code> 方法只选择所需要的内容：</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>result = User.query.with_entities(User.name, User.email).all()</span></span>
<span class="line"><span>for (username, email) in result:</span></span>
<span class="line"><span>    print(username, email)</span></span></code></pre></div><h3 id="每次循环都更新一个对象" tabindex="-1">每次循环都更新一个对象 <a class="header-anchor" href="#每次循环都更新一个对象" aria-label="Permalink to “每次循环都更新一个对象”">​</a></h3><p>避免使用循环来单独更新集合。虽然数据库可以非常快地执行单个更新，但应用程序和数据库服务器之间的往返时间将快速累加。通常，在合理的情况下争取更少的查询。</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>for user in users_to_update:</span></span>
<span class="line"><span>  user.acct_active = True</span></span>
<span class="line"><span>  db.session.add(user)</span></span></code></pre></div><p>改用批量更新方法：</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>query = User.query.filter(user.id.in_([user.id for user in users_to_update]))</span></span>
<span class="line"><span>query.update({&quot;acct_active&quot;: True}, synchronize_session=False)</span></span></code></pre></div><h3 id="触发级联删除" tabindex="-1">触发级联删除 <a class="header-anchor" href="#触发级联删除" aria-label="Permalink to “触发级联删除”">​</a></h3><p>ORM 允许在模型关系上进行简单的配置，但是有一些微妙的行为可能会令人吃惊。大多数数据库通过外键和各种级联选项维护关系完整性。SQLAlchemy 允许你使用外键和级联选项定义模型，但是 ORM 具有自己的级联逻辑，可以取代数据库。</p><p>考虑以下模型：</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>class Artist(Base):</span></span>
<span class="line"><span>    __tablename__ = &quot;artist&quot;</span></span>
<span class="line"><span></span></span>
<span class="line"><span>    id = Column(Integer, primary_key=True)</span></span>
<span class="line"><span>    songs = relationship(&quot;Song&quot;, cascade=&quot;all, delete&quot;)</span></span>
<span class="line"><span></span></span>
<span class="line"><span></span></span>
<span class="line"><span>class Song(Base):</span></span>
<span class="line"><span>    __tablename__ = &quot;song&quot;</span></span>
<span class="line"><span></span></span>
<span class="line"><span>    id = Column(Integer, primary_key=True)</span></span>
<span class="line"><span>    artist_id = Column(Integer, ForeignKey(&quot;artist.id&quot;, ondelete=&quot;CASCADE&quot;))</span></span></code></pre></div><p>删除歌手将导致 ORM 在 <code>song</code> 表上发出 <code>delete</code> 查询，从而防止由于外键导致的删除操作。这种行为可能会成为复杂关系和大量记录的瓶颈。</p><p>请包含 <code>passive_deletes</code> 选项，以确保让数据库来管理关系。但是，请确保你的数据库具有此功能。例如，SQLite 默认情况下不管理外键。</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>songs = relationship(&quot;Song&quot;, cascade  all, delete&quot;, passive_deletes=True)</span></span></code></pre></div><h3 id="当要使用贪婪加载时-应使用延迟加载" tabindex="-1">当要使用贪婪加载时，应使用延迟加载 <a class="header-anchor" href="#当要使用贪婪加载时-应使用延迟加载" aria-label="Permalink to “当要使用贪婪加载时，应使用延迟加载”">​</a></h3><p>延迟加载是 SQLAlchemy 处理关系的默认方法。从上一个例子构建来看，加载一个歌手时不会同时加载他或她的歌曲。这通常是一个好主意，但是如果总是需要加载某些关系，单独的查询可能会造成浪费。</p>`,26)),n("p",null,[s[7]||(s[7]=a("如果允许以延迟方式加载关系，像 ",-1)),i(e,{href:"https://marshmallow.readthedocs.io/en/stable/"},{default:t(()=>[...s[6]||(s[6]=[a("Marshmallow",-1)])]),_:1}),s[8]||(s[8]=a(" 这样流行的序列化框架可以触发级联查询。",-1))]),s[28]||(s[28]=l(`<p>有几种方法可以控制此行为。最简单的方法是通过 relationship 函数本身。</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>songs = relationship(&quot;Song&quot;, lazy=&quot;joined&quot;, cascade=&quot;all, delete&quot;)</span></span></code></pre></div><p>这将导致一个左连接被添加到任何歌手的查询中，因此，<code>songs</code> 集合将立即可用。尽管有更多数据返回给客户端，但往返次数可能会少得多。</p><p>SQLAlchemy 为无法采用这种综合方法的情况提供了更细粒度的控制，可以使用 <code>joinedload()</code> 函数在每个查询的基础上切换连接的加载。</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>from sqlalchemy.orm import joinedload</span></span>
<span class="line"><span></span></span>
<span class="line"><span>artists = Artist.query.options(joinedload(Artist.songs))</span></span>
<span class="line"><span>print(artists.songs) # Does not incur a roundtrip to load</span></span></code></pre></div><h3 id="使用-orm-进行批量记录导入" tabindex="-1">使用 ORM 进行批量记录导入 <a class="header-anchor" href="#使用-orm-进行批量记录导入" aria-label="Permalink to “使用 ORM 进行批量记录导入”">​</a></h3><p>导入成千上万条记录时，构建完整模型实例的开销会成为主要瓶颈。想象一下，从一个文件中加载数千首歌曲记录，其中每首歌曲都先被转换为字典。</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>for song in songs:</span></span>
<span class="line"><span>    db.session.add(Song(\`song))</span></span></code></pre></div><p>相反，绕过 ORM，只使用核心的 SQLAlchemy 参数绑定功能。</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>batch = []</span></span>
<span class="line"><span>insert_stmt = Song.__table__.insert()</span></span>
<span class="line"><span>for song in songs:</span></span>
<span class="line"><span>    if len(batch) &amp;gt; 1000:</span></span>
<span class="line"><span>       db.session.execute(insert_stmt, batch)</span></span>
<span class="line"><span>       batch.clear()</span></span>
<span class="line"><span>    batch.append(song)</span></span>
<span class="line"><span>if batch:</span></span>
<span class="line"><span>    db.session.execute(insert_stmt, batch)</span></span></code></pre></div><p>请记住，此方法会自然而然地跳过你可能依赖的任何客户端 ORM 逻辑，例如基于 Python 的列默认值。尽管此方法比将对象加载为完整的模型实例要快，但是你的数据库可能具有更快的批量加载方法。例如，PostgreSQL 的 <code>COPY</code> 命令为加载大量记录提供了最佳性能。</p><h3 id="过早调用提交或刷新" tabindex="-1">过早调用提交或刷新 <a class="header-anchor" href="#过早调用提交或刷新" aria-label="Permalink to “过早调用提交或刷新”">​</a></h3><p>在很多情况下，你需要将子记录与其父记录相关联，反之亦然。一种显然的方法是刷新会话，以便为有问题的记录分配一个 ID。</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>artist = Artist(name=&quot;Bob Dylan&quot;)</span></span>
<span class="line"><span>song = Song(title=&quot;Mr. Tambourine Man&quot;)</span></span>
<span class="line"><span></span></span>
<span class="line"><span>db.session.add(artist)</span></span>
<span class="line"><span>db.session.flush()</span></span>
<span class="line"><span></span></span>
<span class="line"><span>song.artist_id = artist.id</span></span></code></pre></div><p>对于每个请求，多次提交或刷新通常是不必要的，也是不可取的。数据库刷新涉及强制在数据库服务器上进行磁盘写入，在大多数情况下，客户端将阻塞，直到服务器确认已写入数据为止。</p><p>SQLAlchemy 可以在幕后跟踪关系和管理相关键。</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>artist = Artist(name=&quot;Bob Dylan&quot;)</span></span>
<span class="line"><span>song = Song(title=&quot;Mr. Tambourine Man&quot;)</span></span>
<span class="line"><span></span></span>
<span class="line"><span>artist.songs.append(song)</span></span></code></pre></div><h3 id="总结" tabindex="-1">总结 <a class="header-anchor" href="#总结" aria-label="Permalink to “总结”">​</a></h3><p>我希望这一系列常见的陷阱可以帮助你避免这些问题，并使你的应用平稳运行。通常，在诊断性能问题时，测量是关键。大多数数据库都提供性能诊断功能，可以帮助你定位问题，例如 PostgreSQL 的 <code>pg_stat_statements</code> 模块。</p><hr>`,20)),n("p",null,[s[10]||(s[10]=a("via: ",-1)),i(e,{href:"https://opensource.com/article/19/9/common-pitfalls-python"},{default:t(()=>[...s[9]||(s[9]=[a("https://opensource.com/article/19/9/common-pitfalls-python",-1)])]),_:1})]),n("p",null,[s[15]||(s[15]=a("作者：",-1)),i(e,{href:"https://opensource.com/users/zchtodd"},{default:t(()=>[...s[11]||(s[11]=[a("Zach Todd",-1)])]),_:1}),s[16]||(s[16]=a(" 选题：",-1)),i(e,{href:"https://github.com/lujun9972"},{default:t(()=>[...s[12]||(s[12]=[a("lujun9972",-1)])]),_:1}),s[17]||(s[17]=a(" 译者：",-1)),i(e,{href:"https://github.com/MjSeven"},{default:t(()=>[...s[13]||(s[13]=[a("MjSeven",-1)])]),_:1}),s[18]||(s[18]=a(" 校对：",-1)),i(e,{href:"https://github.com/wxy"},{default:t(()=>[...s[14]||(s[14]=[a("wxy",-1)])]),_:1})]),n("p",null,[s[21]||(s[21]=a("本文由 ",-1)),i(e,{href:"https://github.com/LCTT/TranslateProject"},{default:t(()=>[...s[19]||(s[19]=[a("LCTT",-1)])]),_:1}),s[22]||(s[22]=a(" 原创编译，",-1)),i(e,{href:"https://linux.cn/"},{default:t(()=>[...s[20]||(s[20]=[a("Linux中国",-1)])]),_:1}),s[23]||(s[23]=a(" 荣誉推出",-1))])])}const S=p(h,[["render",c]]);export{C as __pageData,S as default};
